import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as a,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Getting Started with GitHub Copilot","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/copilot/copilot.md","filePath":"products/ai-coding/copilot/copilot.md","lastUpdated":1787042982000}'),s={name:"products/ai-coding/copilot/copilot.md"};function n(r,t,l,d,h,c){return a(),o("div",null,[...t[0]||(t[0]=[i(`<h1 id="getting-started-with-github-copilot" tabindex="-1">Getting Started with GitHub Copilot <a class="header-anchor" href="#getting-started-with-github-copilot" aria-label="Permalink to &quot;Getting Started with GitHub Copilot&quot;">​</a></h1><blockquote><p>This is a <strong>tutorial</strong>. Read it in order and you will go from &quot;Copilot installed&quot; to &quot;I know what each of the four surfaces is for, and how to feed my project conventions to it.&quot;</p><p>Hit an unfamiliar term? See the <a href="./copilot-glossary.html">Glossary</a>. Need a keybinding or a flag? See the <a href="./copilot-cheatsheet.html">Cheatsheet</a>. Want a ready-made recipe for a specific scenario? See the <a href="./copilot-cookbook.html">Cookbook</a>.</p></blockquote><p>Goal of this guide: move Copilot from &quot;autocomplete my line&quot; to &quot;do the work with me.&quot;</p><h2 id="step-0-pick-a-plan" tabindex="-1">Step 0: Pick a plan <a class="header-anchor" href="#step-0-pick-a-plan" aria-label="Permalink to &quot;Step 0: Pick a plan&quot;">​</a></h2><p>Copilot has a free tier — start there:</p><ul><li><strong>Copilot Free</strong> is free, with 2,000 code completions per month, and model selection limited to automatic.</li><li><strong>Students, teachers, and open source maintainers</strong> get it free after eligibility verification.</li><li>Upgrade when the quota bites. Plan prices and limits are in <a href="./copilot-cheatsheet.html">Cheatsheet · Plan comparison</a>.</li></ul><p>One prerequisite fact: Copilot is <strong>not available on GitHub Enterprise Server</strong>. If your company runs self-hosted GHES, confirm this first.</p><h2 id="step-1-install-and-sign-in" tabindex="-1">Step 1: Install and sign in <a class="header-anchor" href="#step-1-install-and-sign-in" aria-label="Permalink to &quot;Step 1: Install and sign in&quot;">​</a></h2><p>Taking VS Code as the example: install the GitHub Copilot extension, sign in with your GitHub account, and you are ready once the Copilot icon appears in the status bar.</p><p>For terminal use, install the CLI separately (<strong>note there are two different CLIs — do not install the wrong one</strong>; the difference is explained in the <a href="./copilot-glossary.html">Glossary</a>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Standalone Copilot CLI (full agent, requires Node.js 22+)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @github/copilot</span></span></code></pre></div><p>Other install methods are in <a href="./copilot-cheatsheet.html">Cheatsheet · Copilot CLI · Install</a>.</p><h2 id="step-2-understand-how-it-knows-your-project" tabindex="-1">Step 2: Understand how it &quot;knows&quot; your project <a class="header-anchor" href="#step-2-understand-how-it-knows-your-project" aria-label="Permalink to &quot;Step 2: Understand how it &quot;knows&quot; your project&quot;">​</a></h2><p>First, correct the most common misconception: <strong>Copilot is not &quot;ChatGPT plus your repository.&quot;</strong></p><p>It is not tied to a single model (the available model set differs by subscription), and it has not trained a model on your repository. It works through <strong>retrieval-based context injection</strong> — the editor assembles the current file, your open tabs, files you explicitly reference, and results retrieved by tools into every single request.</p><p>This mechanism dictates every optimization you can make:</p><table tabindex="0"><thead><tr><th>What you do</th><th>Why it helps</th></tr></thead><tbody><tr><td>Open the relevant files before asking</td><td>Open tabs enter the context</td></tr><tr><td>Reference explicitly with <code>#file:</code></td><td>More reliable than letting it search</td></tr><tr><td>Write custom instructions</td><td>Attached automatically to every request — invest once, benefit long term</td></tr></tbody></table><p>Conversely, &quot;our repo is huge so Copilot must understand it&quot; is wrong. Detailed explanation in <a href="./copilot-glossary.html">Glossary · GitHub Copilot</a>.</p><h2 id="step-3-four-surfaces-each-with-its-own-job" tabindex="-1">Step 3: Four surfaces, each with its own job <a class="header-anchor" href="#step-3-four-surfaces-each-with-its-own-job" aria-label="Permalink to &quot;Step 3: Four surfaces, each with its own job&quot;">​</a></h2><p>Copilot is not one interface; it is four classes of entry point. <strong>Picking the wrong entry point is the single biggest efficiency loss for beginners.</strong></p><table tabindex="0"><thead><tr><th>Surface</th><th>Where</th><th>How you use it</th><th>Typical task</th></tr></thead><tbody><tr><td><strong>Code completion</strong></td><td>Wherever your cursor is in the editor</td><td>Type → ghost text appears → <code>Tab</code></td><td>Complete the next line, fill in boilerplate</td></tr><tr><td><strong>Chat</strong></td><td>Sidebar / inline / terminal</td><td>Conversation</td><td>Explain, refactor, multi-file changes</td></tr><tr><td><strong>CLI</strong></td><td>Terminal</td><td>Interactive agent session</td><td>Command line tasks, scripts</td></tr><tr><td><strong>Cloud agent</strong></td><td>GitHub web / Issue</td><td>Delegate, it runs in the background, produces a PR</td><td>Well-scoped, time-consuming tasks</td></tr></tbody></table><h3 id="_3-1-code-completion" tabindex="-1">3.1 Code completion <a class="header-anchor" href="#_3-1-code-completion" aria-label="Permalink to &quot;3.1 Code completion&quot;">​</a></h3><p>The simplest surface, and the one you plateau on fastest: type, ghost text appears, <code>Tab</code> to accept, <code>Escape</code> to dismiss.</p><p>To make completions sharper, write your intent into a comment:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Filter users active within the last 30 days with a verified email,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// return an array sorted by lastActiveAt descending</span></span></code></pre></div><p>Far more useful than writing &quot;handle users&quot; — the reasoning and patterns are in <a href="./copilot-cookbook.html">Cookbook · Writing code in the editor</a>.</p><h3 id="_3-2-chat-learn-to-pick-the-mode-first" tabindex="-1">3.2 Chat: learn to pick the mode first <a class="header-anchor" href="#_3-2-chat-learn-to-pick-the-mode-first" aria-label="Permalink to &quot;3.2 Chat: learn to pick the mode first&quot;">​</a></h3><p><code>⌃⌘I</code> opens the Chat view; <code>⌘I</code> opens inline Chat in the editor or terminal.</p><p>Chat has three levels of autonomy. <strong>This is the one choice in this whole document you should build muscle memory for:</strong></p><table tabindex="0"><thead><tr><th>Mode</th><th>What it can do</th><th>Signal to pick it</th></tr></thead><tbody><tr><td><strong>Ask</strong></td><td>Answers only, never touches code</td><td>I need to understand this first</td></tr><tr><td><strong>Edit</strong></td><td>Edits the files you specify, you review each diff</td><td>I know where to change, I just don&#39;t want to type it</td></tr><tr><td><strong>Agent</strong></td><td>Decides which files to change, runs commands, iterates over multiple turns</td><td>I know the goal, I don&#39;t want to manage the process</td></tr></tbody></table><p>The rule of thumb: <strong>can you tell at a glance that it got it wrong?</strong> Yes → move toward Agent. No → fall back to Edit, or even Ask.</p><p>Deeper explanation in <a href="./copilot-glossary.html">Glossary · Ask / Edit / Agent</a>; the standard workflow is in <a href="./copilot-cookbook.html">Cookbook · Multi-file changes with Chat</a>.</p><h3 id="_3-3-adding-context-to-chat-and" tabindex="-1">3.3 Adding context to Chat: <code>@</code> and <code>#</code> <a class="header-anchor" href="#_3-3-adding-context-to-chat-and" aria-label="Permalink to &quot;3.3 Adding context to Chat: \`@\` and \`#\`&quot;">​</a></h3><p>Two prefixes, two different jobs:</p><ul><li><strong><code>@</code> is a participant</strong> — it scopes your question to a domain and injects that domain&#39;s context. Today only <code>@github</code>, <code>@terminal</code>, and <code>@vscode</code> exist (plus whatever extensions contribute).</li><li><strong><code>#</code> is tools and file references</strong> — <code>#file:path</code> references a file; <code>#search</code>, <code>#read</code>, <code>#execute</code> and friends are tool sets. Tools provided by MCP servers show up in this same list.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@terminal find the largest file in the src directory</span></span>
<span class="line"><span>#file:gameReducer.js #file:gameInit.js how are these files related</span></span></code></pre></div><blockquote><p><code>@workspace</code>, <code>#editor</code>, <code>#git</code>, and <code>#vscodeAPI</code> — all common in older tutorials — <strong>are no longer on the official list</strong>. Codebase retrieval moved down into tools, which Agent mode invokes on its own. The full retirement list is in the <a href="./copilot-glossary.html">Glossary</a>.</p></blockquote><p>The complete list of participants, tool sets, and slash commands is in the <a href="./copilot-cheatsheet.html">Cheatsheet</a>.</p><h3 id="_3-4-terminal-the-cli" tabindex="-1">3.4 Terminal: the CLI <a class="header-anchor" href="#_3-4-terminal-the-cli" aria-label="Permalink to &quot;3.4 Terminal: the CLI&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">copilot</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # start an interactive session</span></span></code></pre></div><p>Inside a session, <code>@ filename</code> references a file, <code>! command</code> runs a shell command, and <code>Shift+Tab</code> cycles between standard / plan / autopilot.</p><p>The fundamental difference from Chat: <strong>it has side effects</strong> — it really edits files and really runs commands, which is why it has tiered permissions (ask by default / assisted / allow all). For your first sessions, keep the default and read every command it wants to run.</p><h3 id="_3-5-cloud-the-cloud-agent" tabindex="-1">3.5 Cloud: the Cloud agent <a class="header-anchor" href="#_3-5-cloud-the-cloud-agent" aria-label="Permalink to &quot;3.5 Cloud: the Cloud agent&quot;">​</a></h3><p>Delegate a task from a GitHub Issue or the web UI; it opens a branch, changes code, and opens a PR. Suited to work that is &quot;well-scoped, time-consuming, and doesn&#39;t need you watching.&quot; How to write the task description is in <a href="./copilot-cookbook.html">Cookbook · Delegating to the cloud</a>.</p><blockquote><p>Note it used to be called &quot;coding agent&quot;; GitHub has renamed it to cloud agent. Also, <strong>Agent mode</strong> in Chat runs on your local machine — that is not the same thing as the Cloud agent.</p></blockquote><p>Two extra official doors, not part of the day-one drill: <strong>Copilot Chat on github.com</strong> (<code>https://github.com/copilot</code>) and the <strong>Copilot app</strong> (desktop, parallel sessions). When to pick them is on the <a href="./">learning map</a>. <strong>GitHub Spark</strong> is closing — do not start a new app; see <a href="./copilot-cookbook.html">Cookbook · Spark</a>.</p><h2 id="step-4-make-repeated-requirements-permanent" tabindex="-1">Step 4: Make repeated requirements permanent <a class="header-anchor" href="#step-4-make-repeated-requirements-permanent" aria-label="Permalink to &quot;Step 4: Make repeated requirements permanent&quot;">​</a></h2><p>At this point you can use all four surfaces. <strong>The step that actually separates people is this one</strong> — stop re-describing your project conventions every time, and write them into files that Copilot picks up automatically.</p><p>Three mechanisms with different lifecycles:</p><table tabindex="0"><thead><tr><th>Mechanism</th><th>Trigger</th><th>What it solves</th></tr></thead><tbody><tr><td><strong>Custom instructions</strong></td><td>Automatic, attached to every conversation</td><td>Constant constraints (&quot;we use TypeScript strict&quot;)</td></tr><tr><td><strong>Prompt files</strong></td><td>Manual, invoked with <code>/name</code></td><td>Reusable complete tasks (&quot;generate a form from our template&quot;)</td></tr><tr><td><strong>Custom agents</strong></td><td>Switch to that agent</td><td>Role switching (&quot;you are now a code reviewer&quot;)</td></tr></tbody></table><p><strong>Starting with one file is enough</strong> — create <code>.github/copilot-instructions.md</code> at the repository root:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Project conventions</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TypeScript strict mode, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`any\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> is not allowed</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Components are function components with hooks, never class components</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Tests use Vitest</span></span></code></pre></div><p>The test to apply: <strong>if you have written the same sentence in a prompt more than three times, it belongs in custom instructions.</strong></p><p>Authoring details and advanced usage (path-scoped instructions, <code>AGENTS.md</code>, prompt file frontmatter) are in <a href="./copilot-cookbook.html">Cookbook · Capturing project conventions</a> and <a href="./copilot-cheatsheet.html">Cheatsheet · Custom instructions</a>.</p><h2 id="step-5-connect-external-tools-mcp" tabindex="-1">Step 5: Connect external tools (MCP) <a class="header-anchor" href="#step-5-connect-external-tools-mcp" aria-label="Permalink to &quot;Step 5: Connect external tools (MCP)&quot;">​</a></h2><p>When Copilot needs to reach a database, an internal API, or a third-party service, connect an MCP server. Once connected, the tools it provides appear in the <code>#</code> list and are used exactly like built-in tools.</p><blockquote><p><strong>Important currency warning</strong>: the GitHub App form of <strong>Copilot Extensions was sunset on 2025-11-10</strong>, and the official replacement is MCP. The old &quot;invoke an extension with <code>@extension-name</code>&quot; pattern no longer works. VS Code client-side Chat extensions are <strong>unaffected and still supported</strong>. Details in <a href="./copilot-glossary.html">Glossary · MCP</a>.</p></blockquote><h2 id="step-6-build-safety-habits" tabindex="-1">Step 6: Build safety habits <a class="header-anchor" href="#step-6-build-safety-habits" aria-label="Permalink to &quot;Step 6: Build safety habits&quot;">​</a></h2><ul><li><strong>Always review generated code</strong>, especially anything touching permission checks, SQL string building, cryptography, or payments.</li><li><strong>Use automated tests as a guardrail</strong> — confirm the tests are correct first, then let it change the implementation.</li><li>When you need to check whether a suggestion closely matches public code, use the <a href="https://docs.github.com/en/copilot/how-tos/get-code-suggestions/find-matching-code" target="_blank" rel="noreferrer">official matching log</a>.</li><li>Agent mode and the CLI execute commands. <strong>Do not approve a command you are unsure about.</strong></li></ul><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li>Feels like &quot;it never understands me&quot; → <a href="./copilot-cookbook.html">Cookbook · Prompting principles</a></li><li>Looking up a keybinding / command / config key → <a href="./copilot-cheatsheet.html">Cheatsheet</a></li><li>Hit an unfamiliar term, or suspect something you read is out of date → <a href="./copilot-glossary.html">Glossary</a>, especially the retired concepts section</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://docs.github.com/en/copilot" target="_blank" rel="noreferrer">GitHub Copilot documentation</a></li><li><a href="https://code.visualstudio.com/docs/copilot/overview" target="_blank" rel="noreferrer">VS Code Copilot documentation</a></li><li><a href="https://code.visualstudio.com/docs/copilot/reference/copilot-vscode-features" target="_blank" rel="noreferrer">VS Code Copilot feature reference</a></li><li><a href="https://www.youtube.com/playlist?list=PLj6YeMhvp2S5_hvBl2SE-7YCHYlLQ0bPt" target="_blank" rel="noreferrer">GitHub Copilot video series</a></li></ul><p>A fuller list of sources, ordered by reliability, is in <a href="./copilot-cheatsheet.html">Cheatsheet · High-quality sources</a>.</p>`,64)])])}const k=e(s,[["render",n]]);export{f as __pageData,k as default};
